    function run(bytes32 assertionId, address disputeCaller) public {
        // precondition: only test nonzero disputeCaller because the mutant changes behavior for zero address
        require(disputeCaller != address(0), "disputeCaller must be non-zero for this test");

        bool allowed = c.isDisputeAllowed(assertionId, disputeCaller);

        // This assertion holds on the original C implementation (always returns true for any caller)
        // and is violated by the mutant which returns false when disputeCaller == address(0).
        assert(allowed == true);
